=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md (holding registers,
// READY from state only, 1-cycle response latency, SLVERR for unmapped).
`default_nettype none
module axi4_lite_regs #(
  parameter integer ADDR_WIDTH = 4,
  parameter integer DATA_WIDTH = 32
) (
  input  wire                    aclk,
  input  wire                    aresetn,
  input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
  input  wire                    s_axil_awvalid,
  output wire                    s_axil_awready,
  input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
  input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
  input  wire                    s_axil_wvalid,
  output wire                    s_axil_wready,
  output wire [1:0]              s_axil_bresp,
  output wire                    s_axil_bvalid,
  input  wire                    s_axil_bready,
  input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
  input  wire                    s_axil_arvalid,
  output wire                    s_axil_arready,
  output wire [DATA_WIDTH-1:0]   s_axil_rdata,
  output wire [1:0]              s_axil_rresp,
  output wire                    s_axil_rvalid,
  input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH = DATA_WIDTH / 8;
  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  // Control state
  reg                  aw_held;
  reg                  w_held;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [DATA_WIDTH-1:0] rdata_q;

  // Holding registers (reset as well, see notes)
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;

  // Register file
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  // READY is a function of state only
  assign s_axil_awready = !aw_held && !bvalid_q;
  assign s_axil_wready  = !w_held  && !bvalid_q;
  assign s_axil_arready = !rvalid_q;

  assign s_axil_bvalid = bvalid_q;
  assign s_axil_bresp  = bresp_q;
  assign s_axil_rvalid = rvalid_q;
  assign s_axil_rresp  = rresp_q;
  assign s_axil_rdata  = rdata_q;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid  && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;

  // Write path: held copy when one exists, else the live bus
  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

  wire do_write  = (aw_held || aw_hs) && (w_held || w_hs);
  wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                   ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx = wr_addr[3:2];

  wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                   ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx = s_axil_araddr[3:2];

  // Byte mask from strobes
  wire [DATA_WIDTH-1:0] wr_mask;
  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_mask
      assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
    end
  endgenerate

  wire we0 = do_write && wr_mapped && (wr_idx == 2'd0);
  wire we1 = do_write && wr_mapped && (wr_idx == 2'd1);
  wire we2 = do_write && wr_mapped && (wr_idx == 2'd2);
  wire we3 = do_write && wr_mapped && (wr_idx == 2'd3);

  wire [DATA_WIDTH-1:0] reg0_d = (reg0 & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg1_d = (reg1 & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg2_d = (reg2 & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg3_d = (reg3 & ~wr_mask) | (wr_data & wr_mask);

  // Read mux
  reg [DATA_WIDTH-1:0] rd_sel;
  always @* begin
    rd_sel = {DATA_WIDTH{1'b0}};
    case (rd_idx)
      2'd0:    rd_sel = reg0;
      2'd1:    rd_sel = reg1;
      2'd2:    rd_sel = reg2;
      2'd3:    rd_sel = reg3;
      default: rd_sel = {DATA_WIDTH{1'b0}};
    endcase
    if (!rd_mapped) begin
      rd_sel = {DATA_WIDTH{1'b0}};
    end
  end

  // Write channel state
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      w_held    <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_data_q  <= {DATA_WIDTH{1'b0}};
      w_strb_q  <= {STRB_WIDTH{1'b0}};
    end else begin
      if (bvalid_q && s_axil_bready) begin
        bvalid_q <= 1'b0;
      end
      if (do_write) begin
        aw_held  <= 1'b0;
        w_held   <= 1'b0;
        bvalid_q <= 1'b1;
        bresp_q  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_hs) begin
          aw_held   <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
          w_held   <= 1'b1;
          w_data_q <= s_axil_wdata;
          w_strb_q <= s_axil_wstrb;
        end
      end
    end
  end

  // Register file
  always @(posedge aclk) begin
    if (!aresetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else begin
      if (we0) reg0 <= reg0_d;
      if (we1) reg1 <= reg1_d;
      if (we2) reg2 <= reg2_d;
      if (we3) reg3 <= reg3_d;
    end
  end

  // Read channel state
  always @(posedge aclk) begin
    if (!aresetn) begin
      rvalid_q <= 1'b0;
      rresp_q  <= RESP_OKAY;
      rdata_q  <= {DATA_WIDTH{1'b0}};
    end else begin
      if (ar_hs) begin
        rvalid_q <= 1'b1;
        rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
        rdata_q  <= rd_sel;
      end else if (rvalid_q && s_axil_rready) begin
        rvalid_q <= 1'b0;
      end
    end
  end

`ifdef FORMAL
  // Design-intent assertions (not run by this task: no formal_spec submitted)
  reg f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;
  always @(posedge aclk) begin
    if (f_past_valid && !$past(aresetn)) begin
      assert(!bvalid_q);
      assert(!rvalid_q);
      assert(!aw_held);
      assert(!w_held);
    end
  end
  // Never both halves held: the pair fires the write on the completing edge
  always @(*) assert(!(aw_held && w_held));
`endif

endmodule
`default_nettype wire
=== END FILE ===
