// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge; handshakes are sampled
// 1 ns before the rising edge, so there is no race with the design.
`timescale 1ns/1ps
module axi4_lite_regs_tb;
  reg         aclk = 1'b0;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  integer passed;
  integer failed;
  integer i;
  reg [31:0] model [0:3];
  reg [8*64-1:0] nonce;

  always #5 aclk = ~aclk;

  axi4_lite_regs #(.ADDR_WIDTH(4), .DATA_WIDTH(32)) dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready)
  );

  task check(input cond, input [8*56-1:0] msg);
    begin
      if (cond === 1'b1) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("CHECK FAILED at %0t: %0s", $time, msg);
      end
    end
  endtask

  function [31:0] merge(input [31:0] o, input [31:0] d, input [3:0] s);
    begin
      merge = o;
      if (s[0]) merge[7:0]   = d[7:0];
      if (s[1]) merge[15:8]  = d[15:8];
      if (s[2]) merge[23:16] = d[23:16];
      if (s[3]) merge[31:24] = d[31:24];
    end
  endfunction

  // One write: AW raised after aw_dly cycles, W after w_dly cycles,
  // BREADY held low for b_stall cycles once BVALID is seen.
  task axi_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                 input integer aw_dly, input integer w_dly, input integer b_stall);
    integer cyc, lat, k;
    reg aw_done, w_done;
    reg [1:0] exp_resp, held_resp;
    begin
      exp_resp = (addr[1:0] == 2'b00) ? 2'b00 : 2'b10;
      aw_done = 1'b0; w_done = 1'b0; cyc = 0;
      while (!(aw_done && w_done)) begin
        @(negedge aclk);
        if (!aw_done && cyc >= aw_dly) begin awvalid = 1'b1; awaddr = addr; end
        else awvalid = 1'b0;
        if (!w_done && cyc >= w_dly) begin wvalid = 1'b1; wdata = data; wstrb = strb; end
        else wvalid = 1'b0;
        check(bvalid == 1'b0, "no B before both AW and W accepted");
        if (aw_done) check(awready == 1'b0, "AW not re-accepted while held");
        if (w_done)  check(wready == 1'b0, "W not re-accepted while held");
        #4;
        if (awvalid && awready) aw_done = 1'b1;
        if (wvalid && wready)   w_done  = 1'b1;
        cyc = cyc + 1;
        if (cyc > 50) begin
          check(1'b0, "write handshake timeout");
          aw_done = 1'b1; w_done = 1'b1;
        end
      end
      if (exp_resp == 2'b00) model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
      @(negedge aclk);
      awvalid = 1'b0; wvalid = 1'b0;
      lat = 1;
      while (!bvalid && lat < 10) begin @(negedge aclk); lat = lat + 1; end
      check(bvalid == 1'b1, "B arrives");
      check(lat <= 2, "write latency within 2 cycles");
      check(bresp == exp_resp, "BRESP follows address policy");
      held_resp = bresp;
      for (k = 0; k < b_stall; k = k + 1) begin
        check(awready == 1'b0 && wready == 1'b0, "no write accepted while B pending");
        @(negedge aclk);
        check(bvalid == 1'b1 && bresp == held_resp, "B holds under backpressure");
      end
      bready = 1'b1;
      #4;
      check(bvalid == 1'b1, "B handshake");
      @(negedge aclk);
      bready = 1'b0;
      check(bvalid == 1'b0, "BVALID clears after handshake");
      check(awready == 1'b1 && wready == 1'b1, "write channel ready next cycle");
    end
  endtask

  task axi_read(input [3:0] addr, input integer r_stall);
    integer cyc, lat, k;
    reg done;
    reg [31:0] exp_data, hd;
    reg [1:0] exp_resp, hr;
    begin
      exp_resp = (addr[1:0] == 2'b00) ? 2'b00 : 2'b10;
      exp_data = (addr[1:0] == 2'b00) ? model[addr[3:2]] : 32'h0;
      done = 1'b0; cyc = 0;
      while (!done) begin
        @(negedge aclk);
        arvalid = 1'b1; araddr = addr;
        check(rvalid == 1'b0, "no R before AR accepted");
        #4;
        if (arready) done = 1'b1;
        cyc = cyc + 1;
        if (cyc > 50) begin check(1'b0, "read handshake timeout"); done = 1'b1; end
      end
      @(negedge aclk);
      arvalid = 1'b0;
      lat = 1;
      while (!rvalid && lat < 10) begin @(negedge aclk); lat = lat + 1; end
      check(rvalid == 1'b1, "R arrives");
      check(lat <= 2, "read latency within 2 cycles");
      check(rresp == exp_resp, "RRESP follows address policy");
      check(rdata == exp_data, "RDATA matches model");
      if (rdata !== exp_data)
        $error("  addr %h: got %h expected %h", addr, rdata, exp_data);
      hd = rdata; hr = rresp;
      for (k = 0; k < r_stall; k = k + 1) begin
        check(arready == 1'b0, "no read accepted while R pending");
        @(negedge aclk);
        check(rvalid == 1'b1 && rdata == hd && rresp == hr, "R holds under backpressure");
      end
      rready = 1'b1;
      #4;
      check(rvalid == 1'b1, "R handshake");
      @(negedge aclk);
      rready = 1'b0;
      check(rvalid == 1'b0, "RVALID clears after handshake");
      check(arready == 1'b1, "read channel ready next cycle");
    end
  endtask

  initial begin
    #200000;
    failed = failed + 1;
    $error("global timeout");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  initial begin
    passed = 0; failed = 0;
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
    aresetn = 1'b0;
    awaddr = 4'h0; awvalid = 1'b0; wdata = 32'h0; wstrb = 4'h0; wvalid = 1'b0;
    bready = 1'b0; araddr = 4'h0; arvalid = 1'b0; rready = 1'b0;
    for (i = 0; i < 4; i = i + 1) model[i] = 32'h0;

    // Reset
    repeat (3) @(negedge aclk);
    check(bvalid == 1'b0 && rvalid == 1'b0, "responses low during reset");
    aresetn = 1'b1;
    @(negedge aclk);
    check(awready && wready && arready, "READYs high after reset");

    // Reset values
    axi_read(4'h0, 0); axi_read(4'h4, 0); axi_read(4'h8, 0); axi_read(4'hC, 0);

    // Write then read every register (AW and W together)
    axi_write(4'h0, 32'h11223344, 4'hF, 0, 0, 0);
    axi_write(4'h4, 32'h55667788, 4'hF, 0, 0, 0);
    axi_write(4'h8, 32'h99AABBCC, 4'hF, 0, 0, 0);
    axi_write(4'hC, 32'hDDEEFF00, 4'hF, 0, 0, 0);
    axi_read(4'h0, 0); axi_read(4'h4, 0); axi_read(4'h8, 0); axi_read(4'hC, 0);

    // AW before W, W before AW
    axi_write(4'h4, 32'hA5A5A5A5, 4'hF, 0, 3, 0);
    axi_read(4'h4, 0);
    axi_write(4'h8, 32'h5A5A5A5A, 4'hF, 3, 0, 0);
    axi_read(4'h8, 0);
    axi_write(4'h0, 32'hCAFEF00D, 4'hF, 0, 1, 0);
    axi_write(4'hC, 32'h0BADBEEF, 4'hF, 1, 0, 0);
    axi_read(4'h0, 0); axi_read(4'hC, 0);

    // Partial and empty strobes
    axi_write(4'h0, 32'hFFFFFFFF, 4'b0001, 0, 0, 0); axi_read(4'h0, 0);
    axi_write(4'h0, 32'h00000000, 4'b0100, 0, 0, 0); axi_read(4'h0, 0);
    axi_write(4'h4, 32'h12345678, 4'b1010, 2, 0, 0); axi_read(4'h4, 0);
    axi_write(4'h8, 32'h87654321, 4'b0110, 0, 2, 0); axi_read(4'h8, 0);
    axi_write(4'hC, 32'hFFFFFFFF, 4'b0000, 0, 0, 0); axi_read(4'hC, 0);

    // Backpressure on B and R
    axi_write(4'h4, 32'hDEADBEEF, 4'hF, 0, 0, 5);
    axi_read(4'h4, 5);
    axi_write(4'hD, 32'h11111111, 4'hF, 0, 0, 3);
    axi_read(4'hE, 4);

    // SLVERR policy: misaligned writes change nothing, reads return zero
    axi_write(4'h1, 32'h01010101, 4'hF, 0, 0, 0);
    axi_write(4'h6, 32'h02020202, 4'hF, 1, 0, 0);
    axi_write(4'hB, 32'h03030303, 4'hF, 0, 1, 0);
    axi_write(4'hF, 32'h04040404, 4'hF, 0, 0, 0);
    axi_read(4'h1, 0); axi_read(4'h5, 0); axi_read(4'hA, 0); axi_read(4'hF, 0);
    axi_read(4'h0, 0); axi_read(4'h4, 0); axi_read(4'h8, 0); axi_read(4'hC, 0);

    // Back-to-back transactions
    for (i = 0; i < 4; i = i + 1)
      axi_write(i[3:0] << 2, 32'h01000000 * (i + 1) + i, 4'hF, 0, 0, 0);
    for (i = 0; i < 4; i = i + 1)
      axi_read(i[3:0] << 2, 0);

    // Read and write in the same cycle
    @(negedge aclk);
    awvalid = 1'b1; awaddr = 4'h8; wvalid = 1'b1; wdata = 32'hF0F0F0F0; wstrb = 4'hF;
    arvalid = 1'b1; araddr = 4'h4;
    check(awready && wready && arready, "AW, W and AR all ready together");
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    model[2] = 32'hF0F0F0F0;
    check(bvalid == 1'b1 && bresp == 2'b00, "concurrent write answered");
    check(rvalid == 1'b1 && rresp == 2'b00 && rdata == model[1], "concurrent read answered");
    bready = 1'b1; rready = 1'b1;
    @(negedge aclk);
    bready = 1'b0; rready = 1'b0;
    check(bvalid == 1'b0 && rvalid == 1'b0, "both responses taken");
    axi_read(4'h8, 0);

    // Reset during traffic: AW accepted alone, then reset discards it
    @(negedge aclk);
    awvalid = 1'b1; awaddr = 4'h4;
    #4; check(awready == 1'b1, "lone AW accepted");
    @(negedge aclk);
    awvalid = 1'b0;
    check(awready == 1'b0, "AW held, awaiting W");
    aresetn = 1'b0;
    repeat (2) @(negedge aclk);
    aresetn = 1'b1;
    for (i = 0; i < 4; i = i + 1) model[i] = 32'h0;
    check(awready && wready && arready && !bvalid && !rvalid, "clean state after reset");
    // W alone must not complete a write after the discarded AW
    wvalid = 1'b1; wdata = 32'h77777777; wstrb = 4'hF;
    #4; check(wready == 1'b1, "lone W accepted");
    @(negedge aclk);
    wvalid = 1'b0;
    repeat (3) begin
      check(bvalid == 1'b0, "no B from W alone after reset");
      @(negedge aclk);
    end
    // Complete it with an AW to REG3: held W data is used
    awvalid = 1'b1; awaddr = 4'hC;
    #4; check(awready == 1'b1, "late AW accepted");
    @(negedge aclk);
    awvalid = 1'b0;
    model[3] = 32'h77777777;
    check(bvalid == 1'b1 && bresp == 2'b00, "B after late AW");
    bready = 1'b1;
    @(negedge aclk);
    bready = 1'b0;
    axi_read(4'h0, 0); axi_read(4'h4, 0); axi_read(4'h8, 0); axi_read(4'hC, 0);

    repeat (2) @(negedge aclk);
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
